="Ej. Sitio corporativo"></div><div class="field"><label>Dominio autorizado</label><input name="domain" maxlength="190" required placeholder="www.cliente.com"></div></div><div class="webchat-install-help"><i class="fa-solid fa-circle-info"></i><span>La etiqueta es solo para identificar el sitio dentro de ZYNKO. El dominio es el que autoriza técnicamente el widget.</span></div><div class="modal-actions"><button type="button" class="soft modal-close"><i class="fa-solid fa-xmark"></i> Cancelar</button><button class="primary"><i class="fa-solid fa-floppy-disk"></i> Guardar cambios</button></div></form></div></div>
</div><script>document.addEventListener('DOMContentLoaded',()=>{const nivoLayout=document.querySelector('.nivo-webchat-page .webchat-layout'),nivoConfig=nivoLayout?.querySelector(':scope > .panel'),nivoRail=nivoLayout?.querySelector('.nivo-webchat-rail');const syncNivoRail=()=>{if(!nivoConfig||!nivoRail)return;if(window.matchMedia('(min-width:1181px)').matches){nivoRail.style.height=nivoConfig.offsetHeight+'px'}else{nivoRail.style.height=''}};syncNivoRail();window.addEventListener('resize',syncNivoRail,{passive:true});if(window.ResizeObserver&&nivoConfig){new ResizeObserver(syncNivoRail).observe(nivoConfig)}document.querySelectorAll('.webchat-kpi b').forEach(el=>{const end=parseInt(el.textContent,10);if(!Number.isFinite(end)||end<=0)return;const start=performance.now(),duration=520;const tick=now=>{const p=Math.min(1,(now-start)/duration);el.textContent=Math.round(end*(1-Math.pow(1-p,3)));if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)});const post=async fd=>{const r=await fetch(location.href,{method:'POST',body:fd});const j=await r.json();if(!j.ok)throw new Error(j.message);return j};const bind=(id)=>{const f=document.getElementById(id);if(f)f.addEventListener('submit',async e=>{e.preventDefault();try{await post(new FormData(f));showNotify('success','Guardado','Configuración actualizada.');setTimeout(()=>location.reload(),500)}catch(x){showNotify('error','No se pudo guardar',x.message)}})};bind('webchatWidgetForm');bind('installationForm');document.getElementById('copyEmbed')?.addEventListener('click',async()=>{await navigator.clipboard.writeText(document.getElementById('embedCode').textContent);showNotify('success','Copiado','Pega el código en tu sitio web.')});const editModal=document.getElementById('installationEditModal'),editForm=document.getElementById('installationEditForm');document.querySelectorAll('.install-edit').forEach(b=>b.addEventListener('click',()=>{if(!editModal||!editForm)return;editForm.installation_id.value=b.dataset.id||'';editForm.label.value=b.dataset.label||'';editForm.domain.value=b.dataset.domain||'';window.ZynkoModal?.open('#installationEditModal')}));if(editForm)editForm.addEventListener('submit',async e=>{e.preventDefault();try{await post(new FormData(editForm));showNotify('success','Sitio actualizado','El nombre y dominio autorizado quedaron actualizados.');setTimeout(()=>location.reload(),450)}catch(x){showNotify('error','No se pudo actualizar',x.message)}});document.querySelectorAll('.install-toggle').forEach(b=>b.onclick=async()=>{let f=new FormData();f.append('action','webchat_installation_toggle');f.append('installation_id',b.dataset.id);try{await post(f);location.reload()}catch(x){showNotify('error','Error',x.message)}});document.querySelectorAll('.install-delete').forEach(b=>b.onclick=async()=>{const ask=await Swal.fire({title:'Desautorizar sitio',text:'El chat dejará de funcionar inmediatamente en este dominio.',icon:'warning',showCancelButton:true,confirmButtonText:'Sí, desautorizar',cancelButtonText:'Cancelar',allowOutsideClick:false});if(!ask.isConfirmed)return;let f=new FormData();f.append('action','webchat_installation_delete');f.append('installation_id',b.dataset.id);try{await post(f);location.reload()}catch(x){showNotify('error','Error',x.message)}})});</script>
